import fs from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { jobs } from "@/fixtures/jobs";
import { profiles } from "@/fixtures/profiles";
import { skills } from "@/fixtures/skills";
import { levelName } from "@/lib/engine/explain";
import { match } from "@/lib/engine/match";
import { renderProfileReport } from "@/lib/engine/report-text";
import { P } from "./helpers";

// The golden printouts in tests/golden/ were written by hand from the wording
// agreed in the 2.4 plan. They were not generated by the code. If a test here
// fails, the question is always: is the code wrong, or is the hand count?

const golden = (name: string) =>
  fs.readFileSync(fileURLToPath(new URL(`./golden/${name}.txt`, import.meta.url)), "utf8");

const render = (id: string, list = jobs) => renderProfileReport(P(id), list, skills);

describe("golden printouts (hand-written)", () => {
  it("Sam", () => {
    expect(render("sam")).toBe(golden("sam"));
  });

  it("Ana", () => {
    expect(render("ana")).toBe(golden("ana"));
  });

  it("Maya's roadmap: everything blocked, and a dated skill that unlocks nothing yet", () => {
    const report = render("maya");
    expect(report.slice(report.indexOf("=== ROADMAP"))).toBe(
      [
        "=== ROADMAP for Maya Demo (test view: 3 saved jobs; the app shows this from 10) ===",
        "Already Strong: none",
        "",
        "Skills to build, in order: none. No saved job can become a Strong match by skills alone.",
        "",
        "Blocked jobs (skills alone can't make these Strong): 3",
        "  - Operations Analyst, Northwind Logistics: blocked by 1 thing; it can't be closed soon",
        "      (can't be closed soon) The job is in Manchester; the cities on your profile are: Berlin.",
        "  - Financial Planning Analyst, Brightwater Finserv: blocked by 1 thing; it can't be closed soon",
        "      (can't be closed soon) The job is in Bengaluru; the cities on your profile are: Berlin.",
        "  - Frontend Developer, Fjordlight Software: blocked by 1 thing; it can't be closed soon",
        "      (can't be closed soon) The job is remote; your profile accepts: on-site, hybrid.",
        "",
        "Timeline from skills in progress:",
        "  By 2026-12-20 (Python): 0 more Strong matches. Python doesn't unlock a job yet.",
        "",
      ].join("\n"),
    );
  });
});

describe("roadmap wording", () => {
  it("Lena already has a Strong job, so nothing 'other' can become one", () => {
    const report = render("lena");
    expect(report).toContain("Already Strong: 1 job (Frontend Developer, Fjordlight Software)\n");
    expect(report).toContain(
      "Skills to build, in order: none. No other saved job can become a Strong match by skills alone.\n",
    );
  });

  it("Ravi: Power BI is the one skill, and it unlocks Brightwater", () => {
    expect(render("ravi")).toContain(
      "  1. Power BI: unlocks 1 job (Financial Planning Analyst, Brightwater Finserv). Total so far: 1 job.\n",
    );
  });
});

describe("all six profiles", () => {
  const SECTIONS = [
    "--- ",
    "FIT:",
    "WHY:",
    "MUST-HAVES:",
    "CONFLICTS:",
    "NOT CHECKED",
    "CHECK THIS YOURSELF",
    "NICE-TO-HAVES:",
  ];

  it.each(profiles.map((p) => [p.id, p] as const))("%s: sections come in the agreed order", (_id, profile) => {
    const lines = renderProfileReport(profile, jobs, skills).split("\n");
    const seen = lines.flatMap((l) => {
      const hit = SECTIONS.find((s) => l.startsWith(s));
      if (hit) return [hit];
      if (l.startsWith("=== ROADMAP")) return ["=== ROADMAP"];
      return [];
    });
    const expected = [...Array(jobs.length).fill(SECTIONS).flat(), "=== ROADMAP"];
    expect(seen).toEqual(expected);
  });

  it.each(profiles.map((p) => [p.id, p] as const))("%s: the roadmap parts come in the agreed order", (_id, profile) => {
    const report = renderProfileReport(profile, jobs, skills);
    const roadmap = report.slice(report.indexOf("=== ROADMAP")).split("\n");
    const order = ["Already Strong", "Skills to build", "Blocked jobs", "Timeline from skills in progress"];
    const at = order.map((o) => roadmap.findIndex((l) => l.startsWith(o)));
    expect(at.every((i) => i >= 0)).toBe(true);
    expect([...at].sort((a, b) => a - b)).toEqual(at);
  });

  it.each(profiles.map((p) => [p.id, p] as const))("%s: counts only, never a percentage", (_id, profile) => {
    expect(renderProfileReport(profile, jobs, skills)).not.toContain("%");
  });

  it.each(profiles.map((p) => [p.id, p] as const))("%s: every CV line it quotes is really on the CV", (_id, profile) => {
    const quoted = [...renderProfileReport(profile, jobs, skills).matchAll(/CV line (\d+): "(.*)"$/gm)];
    expect(quoted.length).toBeGreaterThan(0);
    for (const [, line, text] of quoted) {
      expect(profile.cvLines[Number(line) - 1]).toBe(text);
    }
  });

  it.each(profiles.map((p) => [p.id, p] as const))("%s: the one-line summaries match the engine's counts", (_id, profile) => {
    const report = renderProfileReport(profile, jobs, skills);
    for (const job of jobs) {
      const r = match(profile, job);
      const label = `${job.title}, ${job.company}`;
      expect(report).toContain(
        `  ${label}: ${levelName(r.level)} (${r.counts.mustsMet} of ${r.counts.mustsTotal} must-haves met`,
      );
    }
  });

  // Hand count of the jobs that have a years conflict, per person:
  // Jonas and Ana on all 3 jobs, Ravi on Fjordlight only, the others none.
  const yearsNotes: Record<string, number> = { maya: 0, jonas: 3, ana: 3, sam: 0, ravi: 1, lena: 0 };
  it.each(Object.entries(yearsNotes))("%s: the 'total years' note is printed once per job that needs it (%i)", (id, count) => {
    const report = render(id);
    const at = report.indexOf("=== ROADMAP");
    const note = "Note: years are compared with your total years of experience, not years per skill.";
    expect(report.slice(0, at).split(note).length - 1).toBe(count);
    expect(report.slice(at).split(note).length - 1).toBe(count);
  });
});

describe("the roadmap label", () => {
  it("says 'test view' with fewer than 10 jobs and nothing with 10 or more", () => {
    const ten = [
      ...jobs,
      ...Array.from({ length: 7 }, (_, i) => ({ ...jobs[0], id: `copy-${i}` })),
    ];
    expect(ten).toHaveLength(10);
    expect(render("sam", ten)).toContain("=== ROADMAP for Sam Example ===\n");
    expect(render("sam")).toContain(
      "=== ROADMAP for Sam Example (test view: 3 saved jobs; the app shows this from 10) ===\n",
    );
  });
});
